export const title = "How to Fit Two Monitors on a Shallow Desk";
export const metaTitle = "How to Fit Two Monitors on a Shallow Desk";
export const metaDescription = "Protect the input area before adding screens. Practical measurements, original diagrams and fit checks for desk layouts in small workspaces.";
export const author = "Jamie Cole, Lead Product Researcher";
